from research_curator import Curator
from finish_school import finish
c=Curator();f=c.fact;pid='2';web='0d011084611eac6e';pdf='6c4af7d38430a1a0';old='UVic ICS 2026–27 fact sheet，September2025版本；不改標2027–28'
f(pid,web,'eligibility','UVic ICS交換限協定校、經母校選派提名；Law與Gustavson Business有獨立交換流程。本公開ICS頁未列GPA硬線，不從Continuing Studies／學位入學頁借門檻。','UVic incoming ICS共通，未標適用學年','partnership agreement')
f(pid,pdf,'language','2026–27 ICS不要求交換生提交UVic英文門檻證明，信任母校挑選；僅供參考iBT90各項20或IELTS6.5各項6。不是臺大英文甄選證明免交，也不是2027–28新要項。',old,'does not require incoming',page=3,period='older_year_reference')
f(pid,web,'deadlines','ICS公開共通流程秋與次春同每年4/1母校提名、4/15學生申請、5/1接受通知；母校提名後才給個人link，不經UVic一般degree admissions或付其初申費。未標當期年，勿自行加2027。','UVic ICS recurring annual schedule，未標year','Each year, the nomination deadline')
f(pid,pdf,'documents','2026–27 ICS學生初申交passport、近照、正式成績與現修課（成績未列時）；母校提名另填姓名、email、term、領域與UG/Grad。入口公開與提名邀請分開，不把ELC／語言班表式當交換文件。',old,'Current passport',page=2,period='older_year_reference')
f(pid,web,'courses','ICS一般本科4–5課／6–7.5units、研2–3課／3–4.5units；ICS本身沒有最低負荷，住宿及study-permit條件另別。Civil Engineering與Law限制，Business/Education/Health/VisualArts及其餘工程有限；先修課須department override，非保證可選。','UVic ICS未標年共通課程；母校認抵及個人permit另核','does not have a minimum courseload requirement')
f(pid,pdf,'housing','舊2026–27要項校寮不保證，住寮每term至少4.5units；須先V00學生號及NetLink ID。最終考後24小時搬出，Term2不允許提前入住，Term1需welcome活動與另申批准；非全ICS最低課量。',old,'minimum of 4.5 UVic units',page=6,period='older_year_reference')
f(pid,web,'housing','ICS校寮有限、抽籤／候補；秋約5月中、春約10月中申請，CAD50申請費；房間限時offer可在開課前才到。ELC住宿5–8月或homestay9–6月的規則屬付費語言班，不借套ICS。','UVic ICS housing共通，未標year；Continuing Studies不同programme','housing application fee is $50 CAD',theme='housing')
f(pid,web,'cost','ICS未標年費頁列MTMI CAD265/4月、抵加4月後BCMSP75/月、U-Pass267/4月（交通/運動/學生會）。舊2026–27PDF則U-Pass260且opt-in，不能把不同版本合成2027確定費率。','UVic ICS public fees未標year；與舊2026–27價別分列','Service Duration',theme='cost')
f(pid,pdf,'insurance_visa','2026–27要項交換自動GuardMe第一4月，約CAD265，限new/unexpected illness/injury；學校移民資訊引導IRCC/ICS，未取得臺灣個案文件裁定。新年度保費及適用情境仍待核。',old,'GuardMe Fee',page=5,period='older_year_reference')
finish(c,pid,'六原正文已讀：ICS與ContinuingStudies/ELC、teen2027、degree prep／PGWP課程不同；後三候選非交換資格文件費。Calendar是3edition更新入口，非初申門檻。2026–27PDF保留原年4/1/2026與4/15/2026，web每年日月不擅改2027；英文證明母校甄選另依NTU。寮4.5units與ICS無最低、U-Pass260optional與web267的版本／範圍分開。')
